select count(*) as n, md5(string_agg(h, '' order by h)) as h from (select md5(concat_ws(chr(31), "path", "title", "kind", "module", "format", "artifact_url", "docs_id", "tab_name", "rev", "content", "pdf_path", "sha256")) h from public.documents where "path" in ('modules/F1-histories-of-making/README.md', 'modules/F1-histories-of-making/atlas/DATA_LICENCES.md', 'modules/F1-histories-of-making/atlas/README.md', 'modules/F1-histories-of-making/atlas/data/register/README.md', 'modules/F1-histories-of-making/atlas/reports/coverage.md', 'modules/F1-histories-of-making/atlas/reports/validation.txt', 'modules/F1-histories-of-making/briefs/BRIEF.md', 'modules/F1-histories-of-making/briefs/BRIEF_ADDENDUM_v2.md', 'modules/F1-histories-of-making/briefs/GROUPING_PAGE_BRIEF.md', 'modules/F1-histories-of-making/briefs/SPEC_BRIEF.md', 'modules/F1-histories-of-making/design/mockups/project/A-Phone.dc.html')) s;